import { buildSectionPage } from '../../../utils/section-page.utils.js';
import { sessionService as defaultService, type SessionService } from '../../../services/session.service.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createComponentLogger } from '../../../utils/component-logger.js';

const template = document.createElement('template');
template.innerHTML = `
    <form class="session-settings" data-testid="form">
        <p>Paste the token <code>npm run session:create</code> printed. The server keeps it as a cookie this app
        cannot read; it is not stored or synced here.</p>
        <label>
            Session token
            <input type="password" name="token" autocomplete="off" required data-testid="token">
        </label>
        <button type="submit" data-testid="submit">Sign in</button>
        <p data-testid="result" hidden></p>
        <pre class="screen-error" data-testid="error" hidden></pre>
    </form>
`;

/** Story 461: swap a pasted token for the session cookie. */
export class SessionSettingsScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private readonly log = createComponentLogger('session-settings-screen');
    private service: SessionService = defaultService;

    setLoading(): void {}
    setError(err: unknown): void { this.showError(err); }
    clearStatus(): void { this.el('error').hidden = true; }

    setService(service: SessionService): void {
        this.service = service;
    }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;
        const page = buildSectionPage(this, 'Session', 'extra', '/extra');
        page.content.appendChild(template.content.cloneNode(true));
        this.el<HTMLFormElement>('form').addEventListener('submit', (event) => {
            event.preventDefault();
            void this.signIn();
        });
    }

    private async signIn(): Promise<void> {
        const input = this.el<HTMLInputElement>('token');
        const submit = this.el<HTMLButtonElement>('submit');
        const result = this.el('result');
        this.clearStatus();
        result.hidden = true;
        submit.disabled = true;
        try {
            const info = await this.service.signIn(input.value);
            input.value = '';
            result.textContent = `Signed in as "${info.label}" until ${info.expires_at}.`;
            result.hidden = false;
        } catch (error) {
            this.log.error('sign-in failed:', error);
            this.showError(error);
        } finally {
            submit.disabled = false;
        }
    }

    private showError(error: unknown): void {
        const el = this.el('error');
        el.hidden = false;
        el.textContent = error instanceof Error ? `${error.message}\n${error.stack ?? ''}` : String(error);
    }

    private el<T extends HTMLElement = HTMLElement>(id: string): T {
        const el = this.querySelector<T>(`[data-testid="${id}"]`);
        if (!el) throw new Error(`session-settings: missing [data-testid="${id}"]`);
        return el;
    }
}

if (!customElements.get('session-settings-screen')) {
    customElements.define('session-settings-screen', SessionSettingsScreen);
}
